/**
 * Public postings (tag "common", T21: any signed-in role). Hand-written from backend
 * app/postings/schemas.py PostingPublicOut. TODO(OpenAPI): replace with types generated by
 * scripts/split-openapi.mjs + openapi-typescript once the routers declare typed response models.
 */
import { apiFetch } from '@/shared/http/client';

export interface JobFamily {
  code: string;
  label: string;
}

/** No weights, custom question or coding problem id/title: those never reach candidates (SEC-04). */
export interface PostingPublic {
  id: string;
  title: string;
  company_name: string;
  company_intro: string | null;
  job_family: string;
  job_family_label: string;
  requirements: string | null;
  preferred: string | null;
  duties: string | null;
  headcount: number | null;
  deadline_date: string | null;
  deadline_at: string | null;
  is_open: boolean;
  coding_enabled: boolean;
  coding_language: string | null;
  coding_time_limit_min: number | null;
  has_applied: boolean;
}

export const fetchJobFamilies = () => apiFetch<JobFamily[]>('/api/job-families');

export function fetchPostings(params: { q?: string; job_family?: string }): Promise<PostingPublic[]> {
  const sp = new URLSearchParams();
  if (params.q) sp.set('q', params.q);
  if (params.job_family) sp.set('job_family', params.job_family);
  const qs = sp.toString();
  return apiFetch<PostingPublic[]>(`/api/postings${qs ? `?${qs}` : ''}`);
}

export const fetchPosting = (id: string) => apiFetch<PostingPublic>(`/api/postings/${encodeURIComponent(id)}`);
